# CPU timing of the 2D deposition (WP-018). No thresholds: the throughput budget of A7 is on the GPU.
#
# Part 1, `prototypes` (deliverable 1, phase 1, before the mechanism is fixed): prototype 2D
# Reference deposition kernels written here, one per candidate mechanism, against a prototype 2D
# Fast (atomic) deposition and the engine's existing 1D deposition at the same particle count:
#   cartesian  a `CartesianIndices` stencil loop over the cells of the node's stencil;
#   valtuple   per-axis tuples with the loop nest generated by recursion on the tuple length
#              (`Val{N}`-style unrolling, generic in N, no CartesianIndex);
#   nested     explicit nested per-axis loops written for N = 2.
# Each is a §0.4 rule 5 kernel (index arithmetic, loads, stores, scalar math), one work item per
# node, the stencil's cells in increasing column-major linear index and within a cell in slot
# order, with no float literal. Run once per thread count:
#   julia +1.13 --project=scripts -t 1 scripts/engine2d/timing.jl prototypes
#   julia +1.13 --project=scripts -t 4 scripts/engine2d/timing.jl prototypes
#
# Part 2, `ported` (deliverable 5, phase 3, on the ported engine): the engine's 2D Reference and
# Fast deposition at the sizes of part 1, next to the `cartesian` prototype timed in the same
# process; an engine-only proxy step (advance, sort, order-2 deposit, order-2 gather) at the CI
# test size of `lib/ParticleMeshCore/test/engine2d_cases.jl` (16 × 12 cells, 2 × 3 per cell); and
# the scratch bytes of the 2D `Workspace` per particle and per cell, with and without a two-array
# extras tuple:
#   julia +1.13 --project=scripts -t 1 scripts/engine2d/timing.jl ported
#   julia +1.13 --project=scripts -t 4 scripts/engine2d/timing.jl ported
#
# Part 3, `cuda` (WP-013): the proxy step of part 2 on the RTX 4080 SUPER, built on the device,
# on 128 × 128 cells at 2 × 2, 8 × 8 and 32 × 32 particles per cell (2^16, 2^20 and 2^24
# particles), Float32 and Float64, Reference and Fast, the GPU synchronized around every timed
# region, with the device bytes of the species, the `Workspace` and the field:
#   julia +1.13 --project=scripts scripts/engine2d/timing.jl cuda
include(joinpath(@__DIR__, "common.jl"))
const PMC = ParticleMesh.ParticleMeshCore
using .PMC: shape_weights, stencil_reach, pick, ALIVE, Stagger, Shape, Species, Workspace, sort_by_cell!, deposit!,
            Reference, Fast, ChargeWeight, PeriodicGrid, field, capacity, gather!
using KernelAbstractions: @kernel, @index, @Const
const Atomix = PMC.Atomix          # the engine's own; no dependency of the scripts environment

const SIZES = ((16, 12), (64, 48))          # cells per axis
const PPC = 64                               # particles per cell (8 × 8 offsets, drawn at random)
const STAGGER_CASES = ((1, "natural", (PMC.Node(), PMC.Node())), (1, "other", (PMC.Center(), PMC.Center())),
                       (2, "natural", (PMC.Center(), PMC.Center())), (2, "other", (PMC.Node(), PMC.Node())))

# ---------------------------------------------------------------------------------------------
# Prototype kernels (part 1)

@inline weights2(shape, st::NTuple{2,Stagger}, δ1, δ2) = (shape_weights(shape, st[1], δ1), shape_weights(shape, st[2], δ2))

"Mechanism `cartesian`: a `CartesianIndices` loop over the stencil's cells."
@kernel function proto_cartesian!(ρ, s, quantity, @Const(seg_start), @Const(seg_stop), shape, st, n::NTuple{2,Int32}, g::Int32,
                                  lo::NTuple{2,Int32}, hi::NTuple{2,Int32})
    I = @index(Global, Cartesian)
    T = eltype(ρ)
    j = (Int32(I[1]) - g, Int32(I[2]) - g)
    cmin = max.(Int32(1), j .- hi)
    cmax = min.(n, j .- lo)
    acc = zero(T)
    @inbounds for C in CartesianIndices((cmin[1]:cmax[1], cmin[2]:cmax[2]))
        c1, c2 = Int32(C[1]), Int32(C[2])
        L = c1 + (c2 - Int32(1)) * n[1]
        for i in seg_start[L]:seg_stop[L]
            (f1, w1), (f2, w2) = weights2(shape, st, s.offset[1][i], s.offset[2][i])
            acc += quantity(s, i) * (pick(w1, j[1] - c1 - f1) * pick(w2, j[2] - c2 - f2))
        end
    end
    @inbounds ρ[I] += acc
end

# The `valtuple` loop nest: the last axis outermost, so the cells come in increasing linear index.
@inline fold_cells(f, acc, ::Tuple{}, ::Tuple{}, c::Tuple) = f(acc, c)
@inline function fold_cells(f, acc, lo::Tuple, hi::Tuple, c::Tuple = ())
    for x in last(lo):last(hi)
        acc = fold_cells(f, acc, Base.front(lo), Base.front(hi), (x, c...))
    end
    return acc
end

struct CellContribution{S,Q,SS,SH,ST,N}
    s::S
    quantity::Q
    seg_start::SS
    seg_stop::SS
    shape::SH
    st::ST
    j::NTuple{N,Int32}
    n::NTuple{N,Int32}
end
@inline function (k::CellContribution{S,Q,SS,SH,ST,N})(acc, c) where {S,Q,SS,SH,ST,N}
    L = c[1]
    stride = Int32(1)
    for d in 2:N
        stride *= k.n[d - 1]
        L += (c[d] - Int32(1)) * stride
    end
    @inbounds for i in k.seg_start[L]:k.seg_stop[L]
        fw = ntuple(d -> shape_weights(k.shape, k.st[d], k.s.offset[d][i]), Val(N))
        wt = ntuple(d -> pick(fw[d][2], k.j[d] - c[d] - fw[d][1]), Val(N))
        acc += k.quantity(k.s, i) * prod(wt)
    end
    return acc
end

"Mechanism `valtuple`: per-axis tuples, the loop nest unrolled by recursion on N."
@kernel function proto_valtuple!(ρ, s, quantity, @Const(seg_start), @Const(seg_stop), shape, st, n::NTuple{N,Int32}, g::Int32,
                                 lo::NTuple{N,Int32}, hi::NTuple{N,Int32}) where {N}
    I = @index(Global, Cartesian)
    T = eltype(ρ)
    j = ntuple(d -> Int32(I[d]) - g, Val(N))
    cmin = max.(Int32(1), j .- hi)
    cmax = min.(n, j .- lo)
    acc = fold_cells(CellContribution(s, quantity, seg_start, seg_stop, shape, st, j, n), zero(T), cmin, cmax)
    @inbounds ρ[I] += acc
end

"Mechanism `nested`: explicit nested loops for N = 2."
@kernel function proto_nested!(ρ, s, quantity, @Const(seg_start), @Const(seg_stop), shape, st, n::NTuple{2,Int32}, g::Int32,
                               lo::NTuple{2,Int32}, hi::NTuple{2,Int32})
    a1, a2 = @index(Global, NTuple)
    T = eltype(ρ)
    j1, j2 = Int32(a1) - g, Int32(a2) - g
    acc = zero(T)
    @inbounds for c2 in max(Int32(1), j2 - hi[2]):min(n[2], j2 - lo[2]), c1 in max(Int32(1), j1 - hi[1]):min(n[1], j1 - lo[1])
        L = c1 + (c2 - Int32(1)) * n[1]
        for i in seg_start[L]:seg_stop[L]
            (f1, w1), (f2, w2) = weights2(shape, st, s.offset[1][i], s.offset[2][i])
            acc += quantity(s, i) * (pick(w1, j1 - c1 - f1) * pick(w2, j2 - c2 - f2))
        end
    end
    @inbounds ρ[a1, a2] += acc
end

"Prototype 2D Fast deposition: one work item per particle, (P+1)² atomic adds."
@kernel function proto_fast!(ρ, s, quantity, shape::Shape{P}, st, g::Int32) where {P}
    i = @index(Global, Linear)
    @inbounds if s.status[i] == ALIVE
        qw = quantity(s, i)
        (f1, w1), (f2, w2) = weights2(shape, st, s.offset[1][i], s.offset[2][i])
        b1 = s.cell[1][i] + f1 + g
        b2 = s.cell[2][i] + f2 + g
        for k2 in 1:(P + 1), k1 in 1:(P + 1)
            Atomix.@atomic ρ[b1 + Int32(k1 - 1), b2 + Int32(k2 - 1)] += qw * (w1[k1] * w2[k2])
        end
    end
end

const MECHANISMS = (cartesian = proto_cartesian!, valtuple = proto_valtuple!, nested = proto_nested!)

"""
    sorted_species_2d(T, n, ppc; seed) -> (s, seg_start, seg_stop)

A 2D species already in sorted order (by column-major linear cell, then slot), `ppc` particles
per cell at offsets from a fixed LCG, with its per-linear-cell segment bounds, built on the host
(the engine has no 2D sort before the port).
"""
function sorted_species_2d(::Type{T}, n, ppc; seed = 1) where {T}
    ncell = prod(n)
    s = Species(CPU(), T, ncell * ppc; q = -1, m = 1, N = 2)
    state = UInt64(seed)
    nextu() = (state = state * 0x5851f42d4c957f2d + 0x14057b7ef767814f; Float64(state >> 11) / 2.0^53)
    seg_start, seg_stop = zeros(Int32, ncell), zeros(Int32, ncell)
    i = 0
    for L in 1:ncell
        c1, c2 = mod1(L, n[1]), (L - 1) ÷ n[1] + 1
        seg_start[L] = i + 1
        for _ in 1:ppc
            i += 1
            s.cell[1][i], s.cell[2][i] = c1, c2
            s.offset[1][i], s.offset[2][i] = T(nextu()), T(nextu())
            s.w[i] = T(1 / 2 + nextu())
            s.status[i] = ALIVE
        end
        seg_stop[L] = i
    end
    fill!(s.count, Int32(i))
    return s, seg_start, seg_stop
end

"The 1D baseline: the same particle count on prod(n) cells, sorted by the engine."
function species_1d(::Type{T}, ncell, ppc; seed = 1) where {T}
    grid = PeriodicGrid(ncell, one(T), 2)
    s = Species(CPU(), T, ncell * ppc; q = -1, m = 1)
    state = UInt64(seed)
    nextu() = (state = state * 0x5851f42d4c957f2d + 0x14057b7ef767814f; Float64(state >> 11) / 2.0^53)
    for i in 1:capacity(s)
        s.cell[1][i] = Int32((i - 1) ÷ ppc + 1)
        s.offset[1][i] = T(nextu())
        s.w[i] = T(1 / 2 + nextu())
        s.status[i] = ALIVE
    end
    fill!(s.count, Int32(capacity(s)))
    ws = Workspace(s, grid)
    sort_by_cell!(s, grid, ws)
    return s, grid, ws
end

function prototype_rows()
    rows = Dict{String,Any}[]
    backend = CPU()
    for T in (Float32, Float64), n in SIZES, (P, label, st) in STAGGER_CASES
        shape = Shape{P}()
        g = Int32(P)
        s, seg_start, seg_stop = sorted_species_2d(T, n, PPC)
        np = capacity(s)
        lo = Int32.(map(x -> stencil_reach(shape, x)[1], st))
        hi = Int32.(map(x -> stencil_reach(shape, x)[2], st))
        dims = n .+ 2P
        results = Dict{String,Any}()
        ref = nothing
        for (name, kern) in pairs(MECHANISMS)
            ρ = KernelAbstractions.zeros(backend, T, dims...)
            run() = kern(backend)(ρ, s, ChargeWeight(), seg_start, seg_stop, shape, st, Int32.(n), g, lo, hi; ndrange = dims)
            run()
            once = copy(ρ)
            ref === nothing && (ref = once)
            results[string(name) * "_bitwise_equal_cartesian"] = once == ref && reinterpret(UInt8, vec(once)) == reinterpret(UInt8, vec(ref))
            results[string(name)] = timed(run)
        end
        ρF = KernelAbstractions.zeros(backend, T, dims...)
        runF() = proto_fast!(backend)(ρF, s, ChargeWeight(), shape, st, g; ndrange = np)
        runF()
        results["fast_max_reldiff"] = maximum(abs.(ρF .- ref)) / maximum(abs, ref)
        results["fast"] = timed(runF)
        s1, grid1, ws1 = species_1d(T, prod(n), PPC)
        ρ1 = field(backend, T, grid1)
        st1 = P == 1 ? (label == "natural" ? PMC.Node() : PMC.Center()) : (label == "natural" ? PMC.Center() : PMC.Node())
        results["ref1d"] = timed(() -> deposit!(Reference(), ρ1, s1, shape, st1, grid1, ws1))
        results["fast1d"] = timed(() -> deposit!(Fast(), ρ1, s1, shape, st1, grid1, ws1))
        for k in ("cartesian", "valtuple", "nested", "fast", "ref1d", "fast1d")
            r = results[k]
            row = Dict{String,Any}("T" => string(T), "cells" => collect(n), "particles" => np, "order" => P, "stagger" => label,
                                   "method" => k, "ns_per_particle" => 1e9 * r.median / np,
                                   "ns_per_particle_min" => 1e9 * r.min / np, "ns_per_particle_max" => 1e9 * r.max / np)
            k in ("cartesian", "valtuple", "nested") && (row["bitwise_equal_cartesian"] = results[k * "_bitwise_equal_cartesian"])
            k == "fast" && (row["max_reldiff_vs_reference"] = results["fast_max_reldiff"])
            push!(rows, row)
        end
        println(T, " ", n, " P=", P, " ", label, ": ",
                join(("$k=$(round(1e9 * results[k].median / np, sigdigits = 3))" for k in ("cartesian", "valtuple", "nested", "fast", "ref1d", "fast1d")), " "))
    end
    return rows
end

const METHOD_ORDER = ("cartesian", "valtuple", "nested", "fast", "ref1d", "fast1d")
const METHOD_LABEL = Dict("cartesian" => "2D Ref, CartesianIndex", "valtuple" => "2D Ref, Val{N} tuples", "nested" => "2D Ref, nested loops",
                          "fast" => "2D Fast (atomics)", "ref1d" => "1D Ref (engine)", "fast1d" => "1D Fast (engine)",
                          "ported_ref" => "2D Ref (ported engine)", "ported_fast" => "2D Fast (ported engine)")

"Grouped bars: one panel per grid size, one group per (T, order, stagger), one bar per method, error bars the spread."
function bars_figure(rows, methods, title)
    fig = Figure(size = (1100, 700))
    cases = [(T, P, l) for T in ("Float32", "Float64") for (P, l, _) in STAGGER_CASES]
    colors = CairoMakie.Makie.wong_colors()
    for (r, n) in enumerate(SIZES)
        ax = Axis(fig[r, 1]; ylabel = "ns per particle", title = "$title, $(n[1]) × $(n[2]) cells, $PPC per cell",
                  xticks = (1:length(cases), ["$(T == "Float32" ? "F32" : "F64") P$P $l" for (T, P, l) in cases]), xticklabelrotation = π / 8)
        w = 0.8 / length(methods)
        for (m, method) in enumerate(methods)
            sel = [only(filter(x -> x["T"] == T && x["order"] == P && x["stagger"] == l && x["cells"] == collect(n) && x["method"] == method, rows))
                   for (T, P, l) in cases]
            xs = (1:length(cases)) .+ (m - (length(methods) + 1) / 2) * w
            barplot!(ax, xs, [x["ns_per_particle"] for x in sel]; width = w, color = colors[m], label = METHOD_LABEL[method])
            rangebars!(ax, xs, [x["ns_per_particle_min"] for x in sel], [x["ns_per_particle_max"] for x in sel]; color = :black)
        end
        r == 1 && axislegend(ax; position = :lt, nbanks = 2)
    end
    return fig
end

function prototypes()
    nt = Threads.nthreads()
    dir = run_dir("prototypes-t$nt", @__FILE__; params = Dict{String,Any}("sizes" => [collect(n) for n in SIZES], "ppc" => PPC,
                                                                          "timer" => "median of 7 samples, each the mean of 5 calls, after one warm-up call"))
    rows = prototype_rows()
    fig = bars_figure(rows, METHOD_ORDER, "Deposition, $nt thread(s), $(cpu_model())")
    save_plot(dir, "prototypes_t$nt", fig, Dict("rows" => rows, "threads" => nt, "cpu" => cpu_model(), "ppc" => PPC))
    println("prototypes: outputs in ", relpath(dir, REPO))
    return dir
end

# ---------------------------------------------------------------------------------------------
# Part 2: the ported engine

"The engine's 2D deposition at the sizes of part 1, next to the `cartesian` prototype in the same process."
function ported_rows()
    rows = Dict{String,Any}[]
    backend = CPU()
    for T in (Float32, Float64), n in SIZES, (P, label, st) in STAGGER_CASES
        shape = Shape{P}()
        s, seg_start, seg_stop = sorted_species_2d(T, n, PPC)
        np = capacity(s)
        grid = PeriodicGrid(n, (one(T), one(T)), P)
        ws = Workspace(s, grid)
        sort_by_cell!(s, grid, ws)
        @assert ws.seg_start == seg_start && ws.seg_stop == seg_stop     # the host-built order is the engine's
        lo = Int32.(map(x -> stencil_reach(shape, x)[1], st))
        hi = Int32.(map(x -> stencil_reach(shape, x)[2], st))
        ρp = field(backend, T, grid)
        runp() = proto_cartesian!(backend)(ρp, s, ChargeWeight(), seg_start, seg_stop, shape, st, Int32.(n), Int32(P), lo, hi;
                                           ndrange = size(ρp))
        ρR, ρF = field(backend, T, grid), field(backend, T, grid)
        runR() = deposit!(Reference(), ρR, s, shape, st, grid, ws)
        runF() = deposit!(Fast(), ρF, s, shape, st, grid, ws)
        runp(); runR()
        same = reinterpret(UInt8, vec(ρp)) == reinterpret(UInt8, vec(ρR))
        for (k, f) in (("cartesian", runp), ("ported_ref", runR), ("ported_fast", runF))
            r = timed(f)
            row = Dict{String,Any}("T" => string(T), "cells" => collect(n), "particles" => np, "order" => P, "stagger" => label,
                                   "method" => k, "ns_per_particle" => 1e9 * r.median / np,
                                   "ns_per_particle_min" => 1e9 * r.min / np, "ns_per_particle_max" => 1e9 * r.max / np)
            k == "ported_ref" && (row["bitwise_equal_prototype"] = same)
            push!(rows, row)
        end
        println(T, " ", n, " P=", P, " ", label, ": ",
                join(("$(r["method"])=$(round(r["ns_per_particle"], sigdigits = 3))" for r in rows[(end - 2):end]), " "), " bitwise=", same)
    end
    return rows
end

"Move every alive particle by `u₁·dt/dx₁`, `u₂·dt/dx₂` cells through the engine's per-axis `advance` (the proxy step's push)."
@kernel function proxy_advance!(s, dt_dx::NTuple{2}, n::NTuple{2,Int32})
    i = @index(Global, Linear)
    @inbounds if s.status[i] == ALIVE
        c, δ = PMC.advance((s.cell[1][i], s.cell[2][i]), (s.offset[1][i], s.offset[2][i]),
                           (s.u[1][i] * dt_dx[1], s.u[2][i] * dt_dx[2]), n)
        s.cell[1][i], s.cell[2][i] = c
        s.offset[1][i], s.offset[2][i] = δ
    end
end

struct ProxyDensity end
@inline (::ProxyDensity)(x, p) = p[1] * (one(p[1]) + p[2] * cos(p[3] * x[1] + p[4] * x[2]))

"""
    proxy_rows(; steps)

The engine-only proxy step at the CI test size: per step, advance, sort (Reference only),
order-2 deposit at (Center, Center) and order-2 gather of the deposited field. CPU ns per
particle-step, median and spread of 7 runs of `steps` steps.
"""
function proxy_rows(; steps = 50)
    rows = Dict{String,Any}[]
    backend = CPU()
    for T in (Float32, Float64), mode in (Reference(), Fast()), (n, ppc) in (((16, 12), (2, 3)), ((16, 12), (8, 8)))
        grid = PeriodicGrid(n, (T(1 // 4), T(3 // 8)), 2)
        s = Species(backend, T, prod(n) * prod(ppc); q = -1, m = 1, N = 2)
        p = (one(T), T(1 // 10), T(2π / (n[1] / 4)), T(2π / (n[2] * 3 / 8)))
        PMC.load_quiet!(s, grid, ProxyDensity(), p, ppc; vth = (T(1 // 5), T(1 // 5), T(1 // 5)), seed = 1, stream = 1)
        ws = Workspace(s, grid)
        ρ = field(backend, T, grid)
        out = similar(s.w)
        st = (PMC.Center(), PMC.Center())
        dt_dx = (T(1 // 2), T(1 // 3))
        step!() = begin
            proxy_advance!(backend)(s, dt_dx, Int32.(n); ndrange = capacity(s))
            mode isa Reference && sort_by_cell!(s, grid, ws)
            fill!(ρ, zero(T))
            deposit!(mode, ρ, s, PMC.Quadratic, st, grid, ws)
            PMC.fold_guards!(ρ, grid)
            PMC.fill_guards!(ρ, grid)
            gather!(out, ρ, s, PMC.Quadratic, st, grid)
        end
        r = timed(() -> foreach(_ -> step!(), 1:steps); reps = 7, inner = 1)
        np = capacity(s)
        push!(rows, Dict{String,Any}("T" => string(T), "mode" => string(nameof(typeof(mode))), "cells" => collect(n), "ppc" => collect(ppc),
                                     "particles" => np, "steps" => steps,
                                     "ns_per_particle_step" => 1e9 * r.median / (np * steps),
                                     "ns_per_particle_step_min" => 1e9 * r.min / (np * steps),
                                     "ns_per_particle_step_max" => 1e9 * r.max / (np * steps)))
        println(rows[end])
    end
    return rows
end

"Scratch of the 2D `Workspace`, split into bytes per particle (capacity) and per linear cell (segment bounds)."
function scratch_rows()
    rows = Dict{String,Any}[]
    for T in (Float32, Float64), extras in (NamedTuple(), (old_cell = Int32, old_offset = T)), (n, ppc) in (((16, 12), 6), ((64, 48), 64))
        grid = PeriodicGrid(n, (one(T), one(T)), 2)
        s = Species(CPU(), T, prod(n) * ppc; q = -1, m = 1, N = 2, extras)
        ws = Workspace(s, grid)
        total = PMC.scratch_bytes(ws)
        cellb = sizeof(ws.seg_start) + sizeof(ws.seg_stop)
        push!(rows, Dict{String,Any}("T" => string(T), "extras" => string(keys(extras)), "cells" => collect(n), "capacity" => capacity(s),
                                     "bytes" => total, "bytes_per_cell" => cellb / prod(n),
                                     "bytes_per_particle" => (total - cellb) / capacity(s)))
        println(rows[end])
    end
    return rows
end

function ported()
    nt = Threads.nthreads()
    dir = run_dir("ported-t$nt", @__FILE__; params = Dict{String,Any}("sizes" => [collect(n) for n in SIZES], "ppc" => PPC,
                                                                      "proxy" => "16x12 cells, 2x3 and 8x8 per cell, 50 steps, 7 runs",
                                                                      "timer" => "median of 7 samples, each the mean of 5 calls, after one warm-up call"))
    rows = ported_rows()
    fig = bars_figure(rows, ("cartesian", "ported_ref", "ported_fast"), "Deposition, ported engine, $nt thread(s), $(cpu_model())")
    save_plot(dir, "ported_t$nt", fig, Dict("rows" => rows, "threads" => nt, "cpu" => cpu_model(), "ppc" => PPC))
    prows = proxy_rows()
    fig = Figure(size = (800, 450))
    labels = ["$(r["T"] == "Float32" ? "F32" : "F64") $(r["mode"]) $(r["ppc"][1])×$(r["ppc"][2])" for r in prows]
    ax = Axis(fig[1, 1]; ylabel = "ns per particle-step", xticks = (1:length(prows), labels), xticklabelrotation = π / 8,
              title = "Engine-only proxy step, 16 × 12 cells, $nt thread(s), $(cpu_model())")
    barplot!(ax, 1:length(prows), [r["ns_per_particle_step"] for r in prows])
    rangebars!(ax, 1:length(prows), [r["ns_per_particle_step_min"] for r in prows], [r["ns_per_particle_step_max"] for r in prows]; color = :black)
    save_plot(dir, "proxy_t$nt", fig, Dict("rows" => prows, "threads" => nt, "cpu" => cpu_model()))
    srows = scratch_rows()
    open(io -> JSON.print(io, Dict("rows" => srows), 2), joinpath(dir, "scratch.json"), "w")
    println("ported: outputs in ", relpath(dir, REPO))
    return dir
end

# Part 3: the proxy step on CUDA

using CUDACore: CUDACore, CUDABackend

const CUDA_CELLS = (128, 128)
const CUDA_PPC = ((2, 2), (8, 8), (32, 32))

"The proxy step of `proxy_rows` on `be`, at `ppc` per cell on `CUDA_CELLS`: ns per particle-step and device bytes."
function proxy_row_device(be, ::Type{T}, mode, ppc; steps = 20) where {T}
    n = CUDA_CELLS
    grid = PeriodicGrid(n, (T(1 // 4), T(3 // 8)), 2)
    local s, ws, ρ, out
    bytes = CUDACore.@allocated begin
        s = Species(be, T, prod(n) * prod(ppc); q = -1, m = 1, N = 2)
        ws = Workspace(s, grid)
        ρ = field(be, T, grid)
        out = similar(s.w)
    end
    p = (one(T), T(1 // 10), T(2π / (n[1] / 4)), T(2π / (n[2] * 3 / 8)))
    PMC.load_quiet!(s, grid, ProxyDensity(), p, ppc; vth = (T(1 // 5), T(1 // 5), T(1 // 5)), seed = 1, stream = 1)
    st = (PMC.Center(), PMC.Center())
    dt_dx = (T(1 // 2), T(1 // 3))
    step!() = begin
        proxy_advance!(be)(s, dt_dx, Int32.(n); ndrange = capacity(s))
        mode isa Reference && sort_by_cell!(s, grid, ws)
        fill!(ρ, zero(T))
        deposit!(mode, ρ, s, PMC.Quadratic, st, grid, ws)
        PMC.fold_guards!(ρ, grid)
        PMC.fill_guards!(ρ, grid)
        gather!(out, ρ, s, PMC.Quadratic, st, grid)
    end
    run() = (foreach(_ -> step!(), 1:steps); KernelAbstractions.synchronize(be))
    run()
    ts = sort([@elapsed(run()) for _ in 1:5])
    np = capacity(s)
    return Dict{String,Any}("T" => string(T), "mode" => string(nameof(typeof(mode))), "cells" => collect(n), "ppc" => collect(ppc),
                            "particles" => np, "steps" => steps, "ns_per_particle_step" => 1e9 * ts[3] / (np * steps),
                            "ns_per_particle_step_min" => 1e9 * ts[1] / (np * steps), "ns_per_particle_step_max" => 1e9 * ts[end] / (np * steps),
                            "device_bytes" => bytes, "device_bytes_per_particle" => bytes / np)
end

function cuda()
    CUDACore.functional() || error("timing.jl cuda: CUDA is not functional on this machine")
    be = CUDABackend()
    gpu = CUDACore.name(CUDACore.device())
    dir = run_dir("cuda", @__FILE__; params = Dict{String,Any}("cells" => collect(CUDA_CELLS), "ppc" => [collect(p) for p in CUDA_PPC],
                                                               "timer" => "median of 5 synchronized runs of 20 steps, after one warm-up run"),
                  work_package = "WP-013", backend = "KernelAbstractions CUDA (CUDACore)",
                  extra = Dict{String,Any}("gpu" => gpu, "cudacore" => string(pkgversion(CUDACore))))
    rows = Dict{String,Any}[]
    for T in (Float32, Float64), mode in (Reference(), Fast()), ppc in CUDA_PPC
        push!(rows, proxy_row_device(be, T, mode, ppc))
        r = rows[end]
        println(r["T"], " ", r["mode"], " ", r["particles"], ": ", round(r["ns_per_particle_step"], sigdigits = 3), " ns/particle-step, ",
                round(r["device_bytes_per_particle"], sigdigits = 3), " B/particle")
        GC.gc(); CUDACore.reclaim()
    end
    fig = Figure(size = (800, 450))
    ax = Axis(fig[1, 1]; xscale = log2, yscale = log10, xlabel = "particles", ylabel = "ns per particle-step",
              title = "Engine-only 2D proxy step, 128 × 128 cells, $gpu")
    for T in ("Float32", "Float64"), mode in ("Reference", "Fast")
        rs = sort([r for r in rows if r["T"] == T && r["mode"] == mode]; by = r -> r["particles"])
        scatterlines!(ax, [r["particles"] for r in rs], [r["ns_per_particle_step"] for r in rs]; label = "$T $mode")
    end
    axislegend(ax)
    save_plot(dir, "proxy_cuda", fig, Dict("rows" => rows, "gpu" => gpu))
    println("cuda: outputs in ", relpath(dir, REPO))
    return dir
end

if abspath(PROGRAM_FILE) == @__FILE__()
    part = isempty(ARGS) ? "prototypes" : ARGS[1]
    part == "prototypes" ? prototypes() : part == "ported" ? ported() : part == "cuda" ? cuda() : error("unknown part $part")
end
